package com.chillingout9.nextstar;

import static com.chillingout9.nextstar.StarRegion.FREMENNIK;
import static com.chillingout9.nextstar.StarRegion.MISTHALIN;
import static com.chillingout9.nextstar.StarRegion.TIRANNWN;
import static com.chillingout9.nextstar.StarRegion.WILDERNESS;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntPredicate;
import org.junit.Test;

public class StarRankerTest
{
	private static final Set<TeleportUnlock> NO_UNLOCKS = EnumSet.noneOf(TeleportUnlock.class);
	private static final Set<TeleportUnlock> GLORY = EnumSet.of(TeleportUnlock.AMULET_OF_GLORY);
	private static final IntPredicate ANY_WORLD = w -> true;

	private final StarRanker ranker = new StarRanker(new TeleportTable());

	// "ranker-test" does not resolve to a known site, so region-level teleport effort applies.
	private static Star star(int world, int tier, int secondsRemaining, StarRegion region)
	{
		return starAt(world, tier, secondsRemaining, "ranker-test", region);
	}

	private static Star starAt(int world, int tier, int secondsRemaining, String locationName, StarRegion region)
	{
		return new Star(world, tier, secondsRemaining, locationName, region, null);
	}

	@Test
	public void emptyInputYieldsEmptyResult()
	{
		assertTrue(ranker.rank(Collections.emptyList(), 1, 0, false, NO_UNLOCKS, ANY_WORLD, RankPriority.HIGHEST_TIER).isEmpty());
	}

	@Test
	public void everythingFilteredYieldsEmptyResult()
	{
		List<Star> stars = Arrays.asList(
			star(1, 6, 1000, MISTHALIN),   // below min tier
			star(2, 9, 10, MISTHALIN));    // inside safety buffer
		assertTrue(ranker.rank(stars, 7, 60, false, NO_UNLOCKS, ANY_WORLD, RankPriority.HIGHEST_TIER).isEmpty());
	}

	@Test
	public void filtersStarsBelowMinTier()
	{
		List<Star> stars = Arrays.asList(star(1, 9, 1000, MISTHALIN), star(2, 6, 1000, MISTHALIN));
		List<Star> ranked = ranker.rank(stars, 7, 0, false, NO_UNLOCKS, ANY_WORLD, RankPriority.HIGHEST_TIER);
		assertEquals(1, ranked.size());
		assertEquals(9, ranked.get(0).getTier());
	}

	@Test
	public void filtersStarsExpiringWithinBuffer()
	{
		List<Star> stars = Arrays.asList(star(1, 9, 30, MISTHALIN), star(2, 9, 120, MISTHALIN));
		List<Star> ranked = ranker.rank(stars, 1, 60, false, NO_UNLOCKS, ANY_WORLD, RankPriority.HIGHEST_TIER);
		assertEquals(1, ranked.size());
		assertEquals(2, ranked.get(0).getWorld());
	}

	@Test
	public void excludesDangerousAreasWhenConfigured()
	{
		List<Star> stars = Arrays.asList(star(1, 9, 1000, WILDERNESS), star(2, 8, 1000, MISTHALIN));
		assertEquals(1, ranker.rank(stars, 1, 0, true, NO_UNLOCKS, ANY_WORLD, RankPriority.HIGHEST_TIER).size());
		assertEquals(2, ranker.rank(stars, 1, 0, false, NO_UNLOCKS, ANY_WORLD, RankPriority.HIGHEST_TIER).size());
	}

	@Test
	public void filtersDisallowedWorlds()
	{
		List<Star> stars = Arrays.asList(star(301, 9, 1000, MISTHALIN), star(302, 9, 1000, MISTHALIN));
		List<Star> ranked = ranker.rank(stars, 1, 0, false, NO_UNLOCKS, w -> w == 302, RankPriority.HIGHEST_TIER);
		assertEquals(1, ranked.size());
		assertEquals(302, ranked.get(0).getWorld());
	}

	@Test
	public void highestTierModeSortsByTierDescending()
	{
		List<Star> stars = Arrays.asList(
			star(1, 7, 1000, MISTHALIN),
			star(2, 9, 1000, MISTHALIN),
			star(3, 8, 1000, MISTHALIN));
		List<Star> ranked = ranker.rank(stars, 1, 0, false, NO_UNLOCKS, ANY_WORLD, RankPriority.HIGHEST_TIER);
		assertEquals(9, ranked.get(0).getTier());
		assertEquals(8, ranked.get(1).getTier());
		assertEquals(7, ranked.get(2).getTier());
	}

	@Test
	public void highestTierModeBreaksTiesByEasierTeleport()
	{
		List<Star> stars = Arrays.asList(star(1, 9, 1000, TIRANNWN), star(2, 9, 1000, MISTHALIN));
		List<Star> ranked = ranker.rank(stars, 1, 0, false, GLORY, ANY_WORLD, RankPriority.HIGHEST_TIER);
		assertEquals(MISTHALIN, ranked.get(0).getRegion());
	}

	@Test
	public void highestTierModeBreaksTeleportTiesByMoreTimeRemaining()
	{
		List<Star> stars = Arrays.asList(star(1, 9, 500, MISTHALIN), star(2, 9, 1500, MISTHALIN));
		List<Star> ranked = ranker.rank(stars, 1, 0, false, NO_UNLOCKS, ANY_WORLD, RankPriority.HIGHEST_TIER);
		assertEquals(1500, ranked.get(0).getSecondsRemaining());
	}

	@Test
	public void easiestTeleportModePrefersReachableOverHigherTier()
	{
		List<Star> stars = Arrays.asList(
			star(1, 9, 1000, TIRANNWN),    // no crystal teleport -> effort 5
			star(2, 8, 1000, MISTHALIN));  // amulet of glory -> effort 2
		List<Star> ranked = ranker.rank(stars, 1, 0, false, GLORY, ANY_WORLD, RankPriority.EASIEST_TELEPORT);
		assertEquals(MISTHALIN, ranked.get(0).getRegion());
	}

	@Test
	public void lunarIsleSinksUnderEasiestTeleportWithoutLunarUnlock()
	{
		List<Star> stars = Arrays.asList(
			starAt(1, 9, 1000, "Lunar Isle mine entrance", FREMENNIK), // far without the lunar teleport
			starAt(2, 8, 1000, "ranker-test", MISTHALIN));             // glory -> effort 2
		List<Star> ranked = ranker.rank(stars, 1, 0, false, GLORY, ANY_WORLD, RankPriority.EASIEST_TELEPORT);
		assertEquals(2, ranked.get(0).getWorld());
	}
}

