package com.chillingout9.nextstar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class StarSitesTest
{
	private static void assertResolves(String feedLabel, String expectedSiteName)
	{
		StarSite site = StarSites.resolve(feedLabel);
		assertNotNull("expected a tile for feed label: " + feedLabel, site);
		assertEquals(feedLabel, expectedSiteName, site.getName());
	}

	@Test
	public void resolvesObservedFeedLabelsToTheCorrectTile()
	{
		assertResolves("Rimmington mine", "Rimmington mine");
		assertResolves("Crafting guild", "Crafting Guild");
		assertResolves("North Crandor", "North Crandor mine");
		assertResolves("Corsair Resource Area", "Corsair Cove Resource Area");
		assertResolves("Corsair Cove bank (innit)", "Corsair Cove");
		assertResolves("Fossil Island rune rocks", "Fossil Island mine");
		assertResolves("Keldagrim entrance mine", "Keldagrim entrance mine");
		assertResolves("Miscellania mine (cip fairy ring)", "Miscellania mine");
		assertResolves("Rellekka mine", "Rellekka mine");
		assertResolves("Lunar Isle mine entrance", "Lunar Isle mine entrance");
		assertResolves("Arceuus dense essence mine", "Dense essence mine");
		assertResolves("Port Piscarilius mine in Kourend", "Port Piscarilius mine");
		assertResolves("Shayzien mine south of Kourend Castle", "Shayzien mine");
		assertResolves("Catherby bank", "Catherby bank");
		assertResolves("Coal Trucks west of Seers'", "Coal Trucks");
		assertResolves("Port Khazard mine", "Port Khazard mine");
		assertResolves("South of Legends' Guild", "Legends' Guild mine");
		assertResolves("Draynor Village", "Draynor Village");
		assertResolves("Canifis bank", "Canifis (bank)");
		assertResolves("Piscatoris (akq fairy ring)", "Piscatoris mine");
		assertResolves("Gnome Stronghold spirit tree", "Tree Gnome Stronghold bank");
		assertResolves("Lletya", "Lletya");
		assertResolves("Mage of Zamorak mine (lvl 7 Wildy)", "South Wilderness mine (Mage of Zamorak)");
		assertResolves("Aldarin mine in Varlamore", "Aldarin mine");
	}

	@Test
	public void prefersTheBankOverTheMineWhenTheLabelSaysBank()
	{
		assertResolves("Al Kharid bank", "Al Kharid (bank)");
		assertResolves("North of Al Kharid PvP Arena", "Emir's Arena");
	}

	@Test
	public void returnsNullForUnknownOrEmptyLabels()
	{
		assertNull(StarSites.resolve("East Falador bank"));
		assertNull(StarSites.resolve(""));
		assertNull(StarSites.resolve(null));
	}
}

