package com.chillingout9.nextstar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.List;
import org.junit.Test;

public class StarMapperTest
{
	private static final Gson GSON = new Gson();

	private static JsonObject obj(String json)
	{
		return GSON.fromJson(json, JsonObject.class);
	}

	@Test
	public void mapsResolvedSiteToTileAndRegion()
	{
		Star star = StarMapper.fromJson(
			obj("{\"world\":301,\"location\":0,\"calledLocation\":\"Rimmington mine\",\"calledAt\":1000.0,\"tier\":8,\"minTime\":null,\"maxTime\":null}"),
			1000L);
		assertNotNull(star);
		assertEquals(301, star.getWorld());
		assertEquals(8, star.getTier());
		assertEquals(StarRegion.ASGARNIA, star.getRegion());
		assertTrue(star.hasRoute());
		assertEquals(2974, star.getWorldPoint().getX());
		assertEquals(3241, star.getWorldPoint().getY());
	}

	@Test
	public void despawnIsReportTimePlusSevenMinutesPerTier()
	{
		// calledAt == now and tier 9, so the full 9 * 7 minutes remain.
		Star star = StarMapper.fromJson(
			obj("{\"world\":1,\"location\":0,\"calledLocation\":\"Rimmington mine\",\"calledAt\":5000.0,\"tier\":9}"),
			5000L);
		assertEquals(9 * StarMapper.SECONDS_PER_TIER, star.getSecondsRemaining());
	}

	@Test
	public void unresolvedSiteFallsBackToRegionAndHasNoRoute()
	{
		Star star = StarMapper.fromJson(
			obj("{\"world\":509,\"location\":0,\"calledLocation\":\"East Falador bank\",\"calledAt\":1000.0,\"tier\":9}"),
			1000L);
		assertNotNull(star);
		assertEquals(StarRegion.ASGARNIA, star.getRegion());
		assertNull(star.getWorldPoint());
		assertFalse(star.hasRoute());
		assertEquals("East Falador bank", star.getLocationName());
	}

	@Test
	public void skipsEntriesMissingEssentialFields()
	{
		assertNull(StarMapper.fromJson(obj("{\"world\":1,\"calledLocation\":\"Rimmington mine\",\"calledAt\":1.0}"), 1L));
		assertNull(StarMapper.fromJson(obj("{\"tier\":9,\"calledLocation\":\"Rimmington mine\",\"calledAt\":1.0}"), 1L));
		assertNull(StarMapper.fromJson(obj("{\"world\":1,\"tier\":0,\"calledLocation\":\"Rimmington mine\",\"calledAt\":1.0}"), 1L));
	}

	@Test
	public void parsesArrayAndDropsInvalidEntries()
	{
		String json = "["
			+ "{\"world\":301,\"location\":0,\"calledLocation\":\"Rimmington mine\",\"calledAt\":1000.0,\"tier\":8},"
			+ "{\"world\":2,\"location\":9,\"calledLocation\":\"Draynor Village\",\"calledAt\":1000.0,\"tier\":7},"
			+ "{\"world\":3,\"location\":0,\"calledAt\":1000.0}"
			+ "]";
		List<Star> stars = StarMapper.fromJsonArray(GSON.fromJson(json, JsonArray.class), 1000L);
		assertEquals(2, stars.size());
	}
}

