package com.chillingout9.nextstar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

import java.util.EnumSet;
import org.junit.Test;

public class TeleportTableTest
{
	private final TeleportTable table = new TeleportTable();

	private static Star star(String locationName, StarRegion region)
	{
		return new Star(1, 9, 1000, locationName, region, null);
	}

	@Test
	public void bestToleratesNullUnlockedSet()
	{
		// Regression: a null unlocked set must not throw; only the always-available option is usable.
		Teleport teleport = table.best(star("ranker-test", StarRegion.MISTHALIN), null);
		assertNotNull(teleport);
		assertEquals(TeleportUnlock.NONE, teleport.getUnlock());
	}

	@Test
	public void bestEffortFallsBackForUnmappedRegion()
	{
		assertEquals(TeleportTable.FALLBACK_EFFORT,
			table.bestEffort(star("ranker-test", StarRegion.UNKNOWN), EnumSet.noneOf(TeleportUnlock.class)));
	}

	@Test
	public void picksLowestEffortUnlockedTeleport()
	{
		Teleport teleport = table.best(star("ranker-test", StarRegion.MISTHALIN), EnumSet.of(TeleportUnlock.AMULET_OF_GLORY));
		assertEquals(2, teleport.getEffort());
	}

	@Test
	public void lunarIsleUsesSiteOverrideNotRegionTeleport()
	{
		Star lunar = star("Lunar Isle mine entrance", StarRegion.FREMENNIK);
		// A Fremennik region teleport (ring of wealth to Miscellania) does not reach Lunar Isle,
		// so without the lunar teleport the best option is the long boat trip.
		assertEquals(5, table.bestEffort(lunar, EnumSet.of(TeleportUnlock.RING_OF_WEALTH)));
		// With the lunar teleport it is a one-click trip.
		assertEquals(1, table.bestEffort(lunar, EnumSet.of(TeleportUnlock.LUNAR_TELEPORT)));
	}
}

