package com.chillingout9.nextstar;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

/**
 * Maps raw feed JSON to {@link Star}. Pure and side-effect free so the mapping (notably
 * the despawn estimate and tile resolution) can be unit-tested without any network.
 * <p>
 * Despawn estimate: a star reported at a given tier has at most {@code tier * 7 minutes}
 * of mining left from the report time, so
 * {@code secondsRemaining = (calledAt + tier * 7min) - now}. This assumes continuous
 * mining, which errs on the early side, the safe direction for the despawn filter.
 */
final class StarMapper
{
	static final int SECONDS_PER_TIER = 7 * 60;

	private StarMapper()
	{
	}

	static List<Star> fromJsonArray(JsonArray array, long nowEpochSeconds)
	{
		List<Star> stars = new ArrayList<>();
		if (array == null)
		{
			return stars;
		}
		for (JsonElement element : array)
		{
			if (element != null && element.isJsonObject())
			{
				Star star = fromJson(element.getAsJsonObject(), nowEpochSeconds);
				if (star != null)
				{
					stars.add(star);
				}
			}
		}
		return stars;
	}

	static Star fromJson(JsonObject obj, long nowEpochSeconds)
	{
		if (obj == null || !has(obj, "world") || !has(obj, "tier"))
		{
			return null;
		}
		int world = obj.get("world").getAsInt();
		int tier = obj.get("tier").getAsInt();
		if (tier < 1 || tier > 9)
		{
			return null;
		}

		String calledLocation = optString(obj, "calledLocation");
		int locationId = has(obj, "location") ? obj.get("location").getAsInt() : -1;

		StarSite site = StarSites.resolve(calledLocation);
		StarRegion region = site != null ? site.getRegion() : StarRegion.fromId(locationId);
		WorldPoint point = site != null ? site.getPoint() : null;

		long anchor = reportAnchor(obj, nowEpochSeconds);
		int secondsRemaining = (int) ((anchor + (long) tier * SECONDS_PER_TIER) - nowEpochSeconds);

		String name = calledLocation != null && !calledLocation.isEmpty()
			? calledLocation
			: region.getDisplayName();

		return new Star(world, tier, secondsRemaining, name, region, point);
	}

	/** When the star's tier was last reported. Prefer calledAt, fall back to maxTime, then now. */
	private static long reportAnchor(JsonObject obj, long nowEpochSeconds)
	{
		if (has(obj, "calledAt"))
		{
			return (long) obj.get("calledAt").getAsDouble();
		}
		if (has(obj, "maxTime"))
		{
			return obj.get("maxTime").getAsLong();
		}
		return nowEpochSeconds;
	}

	private static boolean has(JsonObject obj, String key)
	{
		return obj.has(key) && !obj.get(key).isJsonNull();
	}

	private static String optString(JsonObject obj, String key)
	{
		return has(obj, key) ? obj.get(key).getAsString() : null;
	}
}

