package com.chillingout9.nextstar;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.IntConsumer;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Presentational panel: shows the top recommendation and a short ranked list, with a
 * route action and a world-hop action per entry. Each entry stacks vertically (location,
 * world and time, teleport, then the two buttons) so the location name gets the full panel
 * width instead of being squeezed beside the buttons. The plugin feeds it ranked stars, a
 * function for each star's chosen teleport name, and the callbacks. Call on the Swing EDT.
 */
class NextStarPanel extends PluginPanel
{
	private static final int TIER_COLUMN_WIDTH = 28;
	private static final int MAX_LISTED = 5;
	private static final int LOW_TIME_SECONDS = 5 * 60;
	private static final Color HIGH_TIER = new Color(86, 184, 86);
	private static final Color LOW_TIME = new Color(255, 152, 56);

	private final Consumer<Star> onDrawRoute;
	private final IntConsumer onHop;
	private final JLabel status = new JLabel();
	private final JPanel body = new JPanel();

	NextStarPanel(Consumer<Star> onDrawRoute, IntConsumer onHop)
	{
		this.onDrawRoute = onDrawRoute;
		this.onHop = onHop;

		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(8, 8, 8, 8));

		JPanel header = new JPanel(new BorderLayout());
		header.setBorder(new EmptyBorder(0, 0, 8, 0));
		JLabel title = new JLabel("Next Star");
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		status.setBorder(new EmptyBorder(4, 0, 0, 0));
		header.add(title, BorderLayout.NORTH);
		header.add(status, BorderLayout.SOUTH);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));

		add(header, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);

		showMessage("Enable the star feed in the plugin settings to see suggestions.");
	}

	/** Replace the body with a single wrapped message (disabled / empty / error states). */
	void showMessage(String message)
	{
		status.setText(" ");
		body.removeAll();
		JLabel label = new JLabel(wrap(message));
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(label);
		body.revalidate();
		body.repaint();
	}

	void setStatus(String text)
	{
		status.setText(text);
	}

	/**
	 * Render the recommendation (element 0) and up to four more, using teleportName to
	 * label each star's easiest teleport and the callbacks for the row actions.
	 */
	void displaySuggestions(List<Star> ranked, Function<Star, String> teleportName)
	{
		body.removeAll();

		if (ranked.isEmpty())
		{
			showMessage("No stars match your filters right now.");
			return;
		}

		Star top = ranked.get(0);
		body.add(sectionLabel("Recommended"));
		body.add(buildEntry(top, teleportName.apply(top), true));

		if (ranked.size() > 1)
		{
			body.add(spacer(8));
			body.add(sectionLabel("More active stars"));
			int limit = Math.min(MAX_LISTED, ranked.size());
			for (int i = 1; i < limit; i++)
			{
				Star star = ranked.get(i);
				body.add(spacer(4));
				body.add(buildEntry(star, teleportName.apply(star), false));
			}
		}

		body.add(spacer(10));
		JLabel note = new JLabel(wrap("Hop switches worlds. Routes are drawn by the Shortest Path plugin; install it if a route does nothing."));
		note.setFont(FontManager.getRunescapeSmallFont());
		note.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		note.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(note);

		body.revalidate();
		body.repaint();
	}

	private JPanel buildEntry(Star star, String teleportName, boolean recommended)
	{
		JPanel row = new JPanel(new BorderLayout(0, 4));
		row.setBackground(recommended ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(6, 8, 8, 8));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		// Tier badge plus the location name, which now spans the rest of the width.
		JPanel head = new JPanel(new BorderLayout(6, 0));
		head.setOpaque(false);
		JLabel tier = new JLabel("T" + star.getTier());
		tier.setVerticalAlignment(JLabel.TOP);
		tier.setFont(FontManager.getRunescapeBoldFont().deriveFont(recommended ? 16f : 14f));
		tier.setForeground(star.getTier() >= 8 ? HIGH_TIER : Color.WHITE);
		tier.setPreferredSize(new Dimension(TIER_COLUMN_WIDTH, 0));
		head.add(tier, BorderLayout.WEST);
		JLabel location = new JLabel(star.getLocationName());
		location.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		location.setForeground(Color.WHITE);
		location.setToolTipText(star.getLocationName());
		head.add(location, BorderLayout.CENTER);
		row.add(head, BorderLayout.NORTH);

		// World, time and teleport, indented to line up under the location.
		JPanel details = new JPanel();
		details.setLayout(new BoxLayout(details, BoxLayout.Y_AXIS));
		details.setOpaque(false);
		details.setBorder(new EmptyBorder(0, TIER_COLUMN_WIDTH + 6, 0, 0));
		details.add(timeLine(star));
		details.add(infoLine("Teleport: " + teleportName, ColorScheme.LIGHT_GRAY_COLOR, false));
		row.add(details, BorderLayout.CENTER);

		JPanel buttons = new JPanel(new GridLayout(1, 2, 4, 0));
		buttons.setOpaque(false);
		buttons.setBorder(new EmptyBorder(4, 0, 0, 0));
		buttons.add(buildRouteButton(star, recommended));
		buttons.add(buildHopButton(star));
		row.add(buttons, BorderLayout.SOUTH);

		// Fix the height to the content so the vertical list does not stretch entries.
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private JButton buildRouteButton(Star star, boolean recommended)
	{
		JButton button = textButton(recommended ? "Draw route" : "Route");
		if (star.hasRoute())
		{
			button.setToolTipText("Draw a Shortest Path route to this star");
			button.addActionListener(e -> onDrawRoute.accept(star));
		}
		else
		{
			button.setEnabled(false);
			button.setToolTipText("No mapped tile for this spot yet");
		}
		return button;
	}

	private JButton buildHopButton(Star star)
	{
		JButton button = textButton("Hop");
		button.setToolTipText("Hop to world " + star.getWorld());
		button.addActionListener(e -> onHop.accept(star.getWorld()));
		return button;
	}

	private static JButton textButton(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusable(false);
		return button;
	}

	private static JLabel timeLine(Star star)
	{
		int seconds = star.getSecondsRemaining();
		boolean low = seconds < LOW_TIME_SECONDS;
		return infoLine("W" + star.getWorld() + "  -  " + timeLeft(seconds),
			low ? LOW_TIME : ColorScheme.LIGHT_GRAY_COLOR, false);
	}

	private static String timeLeft(int secondsRemaining)
	{
		if (secondsRemaining <= 0)
		{
			return "expiring";
		}
		int minutes = secondsRemaining / 60;
		return minutes < 1 ? "<1m left" : "~" + minutes + "m left";
	}

	private static JLabel infoLine(String text, Color color, boolean bold)
	{
		JLabel label = new JLabel(text);
		Font base = FontManager.getRunescapeSmallFont();
		label.setFont(bold ? base.deriveFont(Font.BOLD) : base);
		label.setForeground(color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text.toUpperCase());
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.BRAND_ORANGE);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(new EmptyBorder(0, 0, 4, 0));
		return label;
	}

	private static Component spacer(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		spacer.setPreferredSize(new Dimension(1, height));
		spacer.setAlignmentX(Component.LEFT_ALIGNMENT);
		return spacer;
	}

	private static String wrap(String text)
	{
		return "<html><body style='width:190px'>" + text + "</body></html>";
	}
}

