package com.chillingout9.nextstar;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import java.util.function.IntPredicate;

/**
 * Ranks active stars. Pure and deterministic given its inputs, so it is unit-tested in
 * isolation. The plugin reads the dynamic inputs (criteria, unlocks, world eligibility,
 * priority) from config and the world list and passes them in.
 * <p>
 * Stars are filtered, then ordered per {@link RankPriority}. Element 0 is the recommendation.
 * Teleport effort is the easiest unlocked teleport for the star, which accounts for
 * detached sites via {@link TeleportTable}.
 */
public class StarRanker
{
	private final TeleportTable teleportTable;

	public StarRanker(TeleportTable teleportTable)
	{
		this.teleportTable = teleportTable;
	}

	public List<Star> rank(
		List<Star> stars,
		int minTier,
		int safetyBufferSeconds,
		boolean excludeDangerousAreas,
		Set<TeleportUnlock> unlockedTeleports,
		IntPredicate worldAllowed,
		RankPriority priority)
	{
		List<Scored> scored = new ArrayList<>();
		for (Star star : stars)
		{
			if (star.getTier() < minTier)
			{
				continue;
			}
			if (star.getSecondsRemaining() < safetyBufferSeconds)
			{
				continue;
			}
			if (excludeDangerousAreas && star.getRegion().isDangerous())
			{
				continue;
			}
			if (!worldAllowed.test(star.getWorld()))
			{
				continue;
			}
			scored.add(new Scored(star, teleportTable.bestEffort(star, unlockedTeleports)));
		}

		scored.sort(comparatorFor(priority));

		List<Star> ranked = new ArrayList<>(scored.size());
		for (Scored s : scored)
		{
			ranked.add(s.star);
		}
		return ranked;
	}

	private static Comparator<Scored> comparatorFor(RankPriority priority)
	{
		switch (priority)
		{
			case EASIEST_TELEPORT:
				// easiest teleport, then highest tier, then most time remaining
				return Comparator.comparingInt((Scored s) -> s.effort)
					.thenComparingInt(s -> -s.star.getTier())
					.thenComparingInt(s -> -s.star.getSecondsRemaining());
			case BALANCED:
				// tier weighted against effort, then most time remaining
				return Comparator.comparingInt((Scored s) -> -(s.star.getTier() * TIER_WEIGHT - s.effort))
					.thenComparingInt(s -> -s.star.getSecondsRemaining());
			case HIGHEST_TIER:
			default:
				// highest tier, then easiest teleport, then most time remaining
				return Comparator.comparingInt((Scored s) -> -s.star.getTier())
					.thenComparingInt(s -> s.effort)
					.thenComparingInt(s -> -s.star.getSecondsRemaining());
		}
	}

	/** How much one tier is worth against one effort point in the balanced ordering. */
	private static final int TIER_WEIGHT = 2;

	private static final class Scored
	{
		private final Star star;
		private final int effort;

		private Scored(Star star, int effort)
		{
			this.star = star;
			this.effort = effort;
		}
	}
}

