import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Maps stars to candidate {@link Teleport}s and picks the easiest unlocked one.
 * <p>
 * Most regions are scored at the region level, but a few landing sites are far from their
 * region's usual access (Lunar Isle and the other Fremennik isles need a boat, Mos
 * Le'Harmless and the Isle of Souls have their own travel), so those get a site-level
 * override. Every option list includes a {@link TeleportUnlock#NONE} fallback, so a best
 * option always exists.
 */
public class TeleportTable
{
	/** Effort used for an unresolved region and as the worst-case fallback. */
	static final int FALLBACK_EFFORT = 5;

	private static final List<Teleport> FALLBACK =
		Collections.singletonList(new Teleport("Nearest teleport, run", FALLBACK_EFFORT, NONE));

	private final Map<StarRegion, List<Teleport>> byRegion = buildRegions();
	private final Map<String, List<Teleport>> bySite = buildSiteOverrides();

	/**
	 * @return the lowest-effort teleport the player can use for the star, never null. Uses a
	 *         site-level override when the star's spot is detached from its region.
	 */
	public Teleport best(Star star, Set<TeleportUnlock> unlocked)
	{
		return pickBest(optionsFor(star), unlocked);
	}

	/** Convenience for the ranker: the effort of {@link #best}. */
	public int bestEffort(Star star, Set<TeleportUnlock> unlocked)
	{
		return best(star, unlocked).getEffort();
	}

	private List<Teleport> optionsFor(Star star)
	{
		StarSite site = StarSites.resolve(star.getLocationName());
		if (site != null)
		{
			List<Teleport> override = bySite.get(site.getName());
			if (override != null)
			{
				return override;
			}
		}
		return byRegion.getOrDefault(star.getRegion(), FALLBACK);
	}

	private static Teleport pickBest(List<Teleport> options, Set<TeleportUnlock> unlocked)
	{
		Teleport best = null;
		for (Teleport teleport : options)
		{
			boolean usable = teleport.getUnlock() == NONE || (unlocked != null && unlocked.contains(teleport.getUnlock()));
			if (usable && (best == null || teleport.getEffort() < best.getEffort()))
			{
				best = teleport;
			}
		}
		return best != null ? best : FALLBACK.get(0);
	}

	private static Teleport tp(String name, int effort, TeleportUnlock unlock)
	{
		return new Teleport(name, effort, unlock);
