package com.chillingout9.nextstar;

/** How {@link StarRanker} orders stars for the recommendation. */
public enum RankPriority
{
	/** Closest to an unlocked teleport first, then highest tier, then most time. */
	EASIEST_TELEPORT("Easiest teleport first"),
	/** A blend of tier and teleport effort, so a reachable high-tier star wins. */
	BALANCED("Best reachable (balanced)"),
	/** Highest tier first; teleport effort only breaks ties. */
	HIGHEST_TIER("Highest tier first");

	private final String label;

	RankPriority(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

