/**
 * Registry of known shooting-star landing tiles and a resolver from the feed's
 * free-form location label to the closest matching {@link StarSite}.
 * <p>
 * The feed's vocabulary does not match the wiki's verbatim (e.g. the feed says
 * "Coal Trucks west of Seers'", the wiki says "Coal Trucks"), so resolution uses a
 * normalised token-overlap match, accepting a site when it shares at least two tokens
 * with the label or when the site name is wholly contained in the label. A short alias
 * table overrides the handful of labels that token overlap would otherwise mis-map.
 * Unresolved labels return {@code null}; those stars still rank but cannot be routed.
 */
public final class StarSites
{
	private static final Set<String> STOPWORDS = new HashSet<>(Arrays.asList(
		"of", "the", "in", "on", "a", "an", "near", "to", "at", "and"));

	/** Tokens that appear across many sites and so never identify one on their own. */
	private static final Set<String> GENERIC = new HashSet<>(Arrays.asList(
		"mine", "bank", "area", "entrance", "site"));

	/** Directional tokens; an opposing pair between label and site rules out a match. */
	private static final Set<String> DIRECTIONS = new HashSet<>(Arrays.asList(
		"north", "south", "east", "west", "central", "upper", "lower"));

	private static final List<StarSite> SITES = buildSites();
	private static final Map<String, StarSite> NAME_INDEX = buildNameIndex();
	private static final Map<String, StarSite> ALIASES = buildAliases();

	private StarSites()
	{
	}

	/**
	 * @return the closest known landing tile for a feed label, or {@code null} if none
	 *         is a confident match.
	 */
	public static StarSite resolve(String calledLocation)
	{
		if (calledLocation == null)
		{
			return null;
		}
		String norm = normalize(calledLocation);
		if (norm.isEmpty())
		{
			return null;
		}

		// Curated overrides first.
		for (Map.Entry<String, StarSite> alias : ALIASES.entrySet())
		{
			if (norm.contains(alias.getKey()))
			{
				return alias.getValue();
			}
		}

		// A site matches when it shares a non-generic place word with the label and there
		// is no opposing direction (so "East Falador bank" does not match "West Falador
		// mine"). Among matches, prefer the most shared tokens, then the tightest fit.
		Set<String> labelTokens = tokens(norm);
		StarSite best = null;
		int bestShared = 0;
		double bestRatio = 0;
		for (StarSite site : SITES)
		{
			Set<String> siteTokens = tokens(normalize(site.getName()));
			if (!sharesPlaceToken(labelTokens, siteTokens) || hasDirectionalConflict(labelTokens, siteTokens))
			{
				continue;
			}
			int shared = countShared(labelTokens, siteTokens);
			double ratio = (double) shared / siteTokens.size();
			if (shared > bestShared || (shared == bestShared && ratio > bestRatio))
			{
				best = site;
				bestShared = shared;
				bestRatio = ratio;
			}
		}
		return best;
	}

	private static boolean sharesPlaceToken(Set<String> label, Set<String> site)
	{
		for (String token : label)
		{
			if (site.contains(token) && !GENERIC.contains(token) && !DIRECTIONS.contains(token))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean hasDirectionalConflict(Set<String> label, Set<String> site)
	{
		return (label.contains("north") && site.contains("south"))
			|| (label.contains("south") && site.contains("north"))
			|| (label.contains("east") && site.contains("west"))
			|| (label.contains("west") && site.contains("east"));
	}

	private static String normalize(String s)
	{
		return s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", " ").trim();
	}

	private static Set<String> tokens(String norm)
	{
		Set<String> set = new HashSet<>();
		for (String t : norm.split(" "))
		{
			if (t.length() >= 2 && !STOPWORDS.contains(t))
			{
				set.add(t);
			}
		}
		return set;
	}

	private static int countShared(Set<String> a, Set<String> b)
	{
		Set<String> small = a.size() <= b.size() ? a : b;
		Set<String> large = small == a ? b : a;
		int shared = 0;
		for (String t : small)
		{
			if (large.contains(t))
			{
				shared++;
			}
		}
		return shared;
	}

	private static Map<String, StarSite> buildNameIndex()
	{
		Map<String, StarSite> index = new LinkedHashMap<>();
		for (StarSite site : SITES)
		{
			index.put(site.getName(), site);
		}
		return index;
	}

	private static Map<String, StarSite> buildAliases()
	{
		Map<String, StarSite> aliases = new LinkedHashMap<>();
		// "North of Al Kharid PvP Arena" / "Duel Arena" -> Emir's Arena, which token
		// overlap would otherwise lose to "Al Kharid (bank)" / "Al Kharid mine".
		aliases.put("pvp arena", NAME_INDEX.get("Emir's Arena"));
		aliases.put("duel arena", NAME_INDEX.get("Emir's Arena"));
		return aliases;
	}

	private static void add(List<StarSite> sites, StarRegion region, String name, int x, int y)
	{
		sites.add(new StarSite(region, name, new WorldPoint(x, y, 0)));
	}

