package com.chillingout9.nextstar;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Coarse shooting-star regions, mirroring the {@code location} id used by the data feed.
 * <p>
 * Regions drive display grouping, the dangerous-area filter, and region-level teleport
 * scoring in {@link TeleportTable}. The precise landing tiles live in {@link StarSites};
 * a region is only used as a fallback when a specific site cannot be resolved.
 */
@Getter
@RequiredArgsConstructor
public enum StarRegion
{
	ASGARNIA(0, "Asgarnia", false),
	CRANDOR_KARAMJA(1, "Crandor / Karamja", false),
	FELDIP_HILLS(2, "Feldip Hills / Isle of Souls", false),
	FOSSIL_ISLAND(3, "Fossil Island / Mos Le'Harmless", false),
	FREMENNIK(4, "Fremennik / Lunar Isle", false),
	KOUREND(5, "Great Kourend", false),
	KANDARIN(6, "Kandarin", false),
	KEBOS(7, "Kebos Lowlands", false),
	KHARIDIAN_DESERT(8, "Kharidian Desert", false),
	MISTHALIN(9, "Misthalin", false),
	MORYTANIA(10, "Morytania", false),
	PISCATORIS_GNOME(11, "Piscatoris / Gnome Stronghold", false),
	TIRANNWN(12, "Tirannwn", false),
	WILDERNESS(13, "Wilderness", true),
	CORSAIR(14, "Corsair Cove", false),
	VARLAMORE(15, "Varlamore", false),
	UNKNOWN(-1, "Unknown", false);

	private final int id;
	private final String displayName;
	private final boolean dangerous;

	public static StarRegion fromId(int id)
	{
		for (StarRegion region : values())
		{
			if (region.id == id)
			{
				return region;
			}
		}
		return UNKNOWN;
	}
}

