package com.chillingout9.nextstar;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches active stars from the configured crowdsourcing endpoint. The request runs on
 * the OkHttp thread pool via {@link Call#enqueue}, never on the client thread, and the
 * {@link Callback} is invoked from that pool. The Authorization header carries the user's
 * key from config; nothing is bundled.
 */
@Slf4j
@Singleton
public class HttpStarDataSource implements StarDataSource
{
	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final NextStarConfig config;

	@Inject
	HttpStarDataSource(OkHttpClient okHttpClient, Gson gson, NextStarConfig config)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.config = config;
	}

	@Override
	public void fetchActiveStars(Callback callback)
	{
		Request request;
		try
		{
			Request.Builder builder = new Request.Builder().url(config.endpointUrl());
			// The feed is live data, so bypass RuneLite's shared OkHttp disk cache and always
			// hit the network; otherwise a cached response replays stale stars across refreshes.
			builder.cacheControl(CacheControl.FORCE_NETWORK);
			String key = config.authorizationKey();
			if (key != null && !key.isEmpty())
			{
				builder.addHeader("Authorization", key);
			}
			request = builder.build();
		}
		catch (IllegalArgumentException e)
		{
			callback.onError("Invalid endpoint URL in settings.");
			return;
		}

		okHttpClient.newCall(request).enqueue(new okhttp3.Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Star feed request failed", e);
				callback.onError("Could not reach the star feed.");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						callback.onError("Star feed returned HTTP " + response.code() + ".");
						return;
					}
					JsonArray array = gson.fromJson(body.string(), JsonArray.class);
					long now = Instant.now().getEpochSecond();
					log.debug("Next Star: feed returned {} entries", array == null ? 0 : array.size());
					callback.onStars(StarMapper.fromJsonArray(array, now));
				}
				catch (IOException | JsonSyntaxException | IllegalStateException e)
				{
					log.debug("Could not parse star feed response", e);
					callback.onError("Could not read the star feed.");
				}
			}
		});
	}
}

