package com.chillingout9.nextstar;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.IntPredicate;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.WorldUtil;
import net.runelite.http.api.worlds.World;
import net.runelite.http.api.worlds.WorldResult;
import net.runelite.http.api.worlds.WorldType;

@Slf4j
@PluginDescriptor(
	name = "Next Star",
	description = "Recommends the highest-tier active shooting star with the easiest teleport and routes to it",
	tags = {"shooting", "star", "stars", "mining", "teleport", "route"}
)
public class NextStarPlugin extends Plugin
{
	private static final String SHORTEST_PATH_NAMESPACE = "shortestpath";
	private static final String SHORTEST_PATH_DRAW = "path";

	private static final Set<WorldType> DANGEROUS_WORLDS = EnumSet.of(
		WorldType.PVP, WorldType.HIGH_RISK, WorldType.DEADMAN, WorldType.TOURNAMENT);

	@Inject
	private NextStarConfig config;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private EventBus eventBus;

	@Inject
	private WorldService worldService;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private HttpStarDataSource httpStarDataSource;

	private final StarDataSource sampleStarDataSource = new StubStarDataSource();
	private final TeleportTable teleportTable = new TeleportTable();
	private final StarRanker ranker = new StarRanker(teleportTable);

	private NextStarPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> refreshFuture;

	private static final int DISPLAY_SWITCHER_MAX_ATTEMPTS = 3;
	private net.runelite.api.World quickHopTargetWorld;
	private int displaySwitcherAttempts;

	/** Consecutive feed errors; the first is shown as "loading" to avoid a transient blip at startup. */
	private volatile int consecutiveFeedErrors;

	@Override
	protected void startUp()
	{
		panel = new NextStarPanel(this::drawRoute, this::hopTo);

		BufferedImage icon = ImageUtil.loadImageResource(NextStarPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Next Star")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		scheduleRefresh();
	}

	@Override
	protected void shutDown()
	{
		if (refreshFuture != null)
		{
			refreshFuture.cancel(true);
			refreshFuture = null;
		}
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		// executor is the shared injected scheduler; only our task is cancelled, not the pool.
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (NextStarConfig.GROUP.equals(event.getGroup()))
		{
			// Re-schedule in case the interval changed, and refresh immediately.
			scheduleRefresh();
		}
	}

	@Provides
	NextStarConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NextStarConfig.class);
	}

	private void scheduleRefresh()
	{
		if (refreshFuture != null)
		{
			refreshFuture.cancel(false);
		}
		refreshFuture = executor.scheduleWithFixedDelay(
			this::refresh, 0, config.refreshIntervalSeconds(), TimeUnit.SECONDS);
	}

	/**
	 * Runs on the scheduler thread. Wrapped so a thrown exception cannot cancel the
	 * recurring task. Chooses the data source from config and renders the result.
	 */
	private void refresh()
	{
		try
		{
			if (config.useSampleData())
			{
				fetchAndRender(sampleStarDataSource, true);
			}
			else if (config.enableFeed())
			{
				fetchAndRender(httpStarDataSource, false);
			}
			else
			{
				updatePanel(p -> p.showMessage(
					"Enable the star feed in the plugin settings to see suggestions."));
			}
		}
		catch (Exception e)
		{
			log.debug("Next Star refresh failed", e);
		}
	}

	private void fetchAndRender(StarDataSource source, boolean sampleData)
	{
		final IntPredicate worldAllowed = buildWorldFilter();
		final Set<TeleportUnlock> unlocked = unlockedTeleports();
		final int minTier = config.minTier();
		final int buffer = config.minimumMinutesRemaining() * 60;
		final boolean excludeDangerous = config.excludeDangerousAreas();
		final RankPriority priority = config.rankPriority();

		source.fetchActiveStars(new StarDataSource.Callback()
		{
			@Override
			public void onStars(List<Star> stars)
			{
				consecutiveFeedErrors = 0;
				List<Star> ranked = ranker.rank(stars, minTier, buffer, excludeDangerous, unlocked, worldAllowed, priority);
				String status = sampleData
					? "SAMPLE DATA (not live), " + ranked.size() + " stars"
					: ranked.size() + " star(s) after filters";
				updatePanel(p ->
				{
					p.setStatus(status);
					p.displaySuggestions(ranked, star -> teleportTable.best(star, unlocked).getName());
				});
			}

			@Override
			public void onError(String message)
			{
				// Mask the first error as "loading" so a transient blip at startup is not alarming.
				int errors = ++consecutiveFeedErrors;
				String shown = errors <= 1 ? "Loading the star feed..." : message;
				updatePanel(p -> p.showMessage(shown));
			}
		});
	}

	/** Posts the star's tile to the Shortest Path plugin. No-op if it has no mapped tile. */
	private void drawRoute(Star star)
	{
		final WorldPoint target = star.getWorldPoint();
		if (target == null)
		{
			return;
		}
		// Post on the client thread so Shortest Path can safely read game state (e.g. the
		// player's location when it fills in the route start).
		clientThread.invoke(() ->
		{
			Map<String, Object> data = new HashMap<>();
			data.put("target", target);
			eventBus.post(new PluginMessage(SHORTEST_PATH_NAMESPACE, SHORTEST_PATH_DRAW, data));
		});
	}

	/** Hops to a world using RuneLite's world-hop API. User-initiated, like the core World Hopper. */
	private void hopTo(int worldId)
	{
		clientThread.invoke(() -> startHop(worldId));
	}

	private void startHop(int worldId)
	{
		WorldResult worldResult = worldService.getWorlds();
		if (worldResult == null)
		{
			return;
		}
		World world = worldResult.findWorld(worldId);
		if (world == null)
		{
			return;
		}

		net.runelite.api.World rsWorld = client.createWorld();
		rsWorld.setActivity(world.getActivity());
		rsWorld.setAddress(world.getAddress());
		rsWorld.setId(world.getId());
		rsWorld.setPlayerCount(world.getPlayers());
		rsWorld.setLocation(world.getLocation());
		rsWorld.setTypes(WorldUtil.toWorldTypes(world.getTypes()));

		if (client.getGameState() == GameState.LOGIN_SCREEN)
		{
			client.changeWorld(rsWorld);
			return;
		}
		quickHopTargetWorld = rsWorld;
		displaySwitcherAttempts = 0;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Quick-hop sequence: open the world switcher, then hop once it has loaded.
		if (quickHopTargetWorld == null)
		{
			return;
		}
		if (client.getWidget(InterfaceID.Worldswitcher.BUTTONS) == null)
		{
			client.openWorldHopper();
			if (++displaySwitcherAttempts >= DISPLAY_SWITCHER_MAX_ATTEMPTS)
			{
				quickHopTargetWorld = null;
				displaySwitcherAttempts = 0;
			}
		}
		else
		{
			client.hopToWorld(quickHopTargetWorld);
			quickHopTargetWorld = null;
			displaySwitcherAttempts = 0;
		}
	}

	/** The teleports the player has ticked in config, assembled into a set. */
	private Set<TeleportUnlock> unlockedTeleports()
	{
		EnumSet<TeleportUnlock> unlocked = EnumSet.noneOf(TeleportUnlock.class);
		addIf(unlocked, config.teleStandardSpellbook(), TeleportUnlock.STANDARD_SPELLBOOK);
		addIf(unlocked, config.teleAmuletOfGlory(), TeleportUnlock.AMULET_OF_GLORY);
		addIf(unlocked, config.teleRingOfDueling(), TeleportUnlock.RING_OF_DUELING);
		addIf(unlocked, config.teleRingOfWealth(), TeleportUnlock.RING_OF_WEALTH);
		addIf(unlocked, config.teleGamesNecklace(), TeleportUnlock.GAMES_NECKLACE);
		addIf(unlocked, config.teleSkillsNecklace(), TeleportUnlock.SKILLS_NECKLACE);
		addIf(unlocked, config.teleCombatBracelet(), TeleportUnlock.COMBAT_BRACELET);
		addIf(unlocked, config.teleDigsitePendant(), TeleportUnlock.DIGSITE_PENDANT);
		addIf(unlocked, config.teleXericsTalisman(), TeleportUnlock.XERICS_TALISMAN);
		addIf(unlocked, config.teleFairyRings(), TeleportUnlock.FAIRY_RINGS);
		addIf(unlocked, config.teleSpiritTree(), TeleportUnlock.SPIRIT_TREE);
		addIf(unlocked, config.teleMiningCape(), TeleportUnlock.MINING_CAPE);
		addIf(unlocked, config.teleCraftingCape(), TeleportUnlock.CRAFTING_CAPE);
		addIf(unlocked, config.teleKourendTeleport(), TeleportUnlock.KOUREND_TELEPORT);
		addIf(unlocked, config.teleVarlamoreTeleport(), TeleportUnlock.VARLAMORE_TELEPORT);
		addIf(unlocked, config.teleCrystalTeleport(), TeleportUnlock.CRYSTAL_TELEPORT);
		addIf(unlocked, config.teleLunarTeleport(), TeleportUnlock.LUNAR_TELEPORT);
		return unlocked;
	}

	private static void addIf(Set<TeleportUnlock> set, boolean unlocked, TeleportUnlock teleport)
	{
		if (unlocked)
		{
			set.add(teleport);
		}
	}

	/** Snapshot the world list into a predicate: drop dangerous worlds and apply the members filter. */
	private IntPredicate buildWorldFilter()
	{
		WorldResult worldResult = worldService.getWorlds();
		WorldFilter filter = config.worldFilter();

		Map<Integer, Set<WorldType>> typesByWorld = new HashMap<>();
		if (worldResult != null && worldResult.getWorlds() != null)
		{
			for (World world : worldResult.getWorlds())
			{
				typesByWorld.put(world.getId(), world.getTypes());
			}
		}

		return world ->
		{
			Set<WorldType> types = typesByWorld.get(world);
			if (types == null)
			{
				return true; // unknown world; do not drop it
			}
			for (WorldType dangerous : DANGEROUS_WORLDS)
			{
				if (types.contains(dangerous))
				{
					return false;
				}
			}
			boolean members = types.contains(WorldType.MEMBERS);
			if (filter == WorldFilter.MEMBERS_ONLY && !members)
			{
				return false;
			}
			return filter != WorldFilter.FREE_ONLY || !members;
		};
	}

	private void updatePanel(java.util.function.Consumer<NextStarPanel> action)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				action.accept(panel);
			}
		});
	}
}

