package com.chillingout9.nextstar;

import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * A single shooting-star landing tile. Coordinates are sourced from the OSRS Wiki
 * "Shooting Stars" page. Instances are held in the {@link StarSites} registry, which
 * also resolves a feed location string to the closest matching site.
 */
@Value
public class StarSite
{
	StarRegion region;
	String name;
	WorldPoint point;
}
